mapper.select:
SELECT DATE_FORMAT(access_date, '%Y-%m-%d') AS date,
       SUM(total_access_count) AS access_count
FROM table_access_daily
WHERE cluster_id = #{clusterId}
  AND db_name = #{dbName}
  AND table_name = #{tableName}
  AND access_date >= #{startDate}
GROUP BY access_date
ORDER BY access_date

SELECT cluster_id, db_name, table_name, SUM(CASE WHEN access_date >= #{hotStart} THEN total_access_count ELSE 0 END) AS access_count, MAX(last_access_time) AS last_access_time FROM table_access_daily WHERE access_date >= #{historyStart} AND cluster_id IN
#{clusterId}
GROUP BY cluster_id, db_name, table_name
